// features/vendor-lifecycle.feature: "A vendor that was sent back can be edited again"
import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type DocumentOut = { id: string; status: string };
type ExtractionOut = { id: string; status: string };
type VendorOut = { id: string; name: string; status: string };

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Polls a document until extraction finishes, then returns its extraction. */
async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<ExtractionOut> {
  for (let attempt = 0; attempt < 100; attempt++) {
    const document = await expectStatus<DocumentOut>(await member.get(`/api/documents/${documentId}`), 200);
    if (document.status === "extracted") {
      return expectStatus<ExtractionOut>(await member.get(`/api/documents/${documentId}/extraction`), 200);
    }
    if (document.status === "failed") {
      throw new Error(`Document ${documentId} failed extraction`);
    }
    await sleep(200);
  }
  throw new Error(`Document ${documentId} did not finish extraction in time`);
}

test.describe("vendor lifecycle", () => {
  test("a vendor that was sent back can be edited again", { tag: "@LIF-09" }, async ({ apiAs }) => {
    // Arrange: member creates a unique vendor, uploads a contract, and submits it.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const suffix = uniqueSuffix();

    const created = await expectStatus<VendorOut>(
      await member.post("/api/vendors", {
        data: {
          name: `LIF-09 Vendor ${suffix}`,
          category: "services",
          contact_email: `lif-09+${suffix}@example.test`,
        },
      }),
      201,
    );

    const document = await expectStatus<DocumentOut>(
      await member.post(`/api/vendors/${created.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: `contract-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 LIF-09 contract"),
          },
        },
      }),
      201,
    );

    const extraction = await waitForExtraction(member, document.id);

    await expectStatus<VendorOut>(await member.post(`/api/vendors/${created.id}/submit`), 200);

    // Arrange: reviewer rejects the contract extraction, sending the vendor back.
    const decided = await expectStatus<ExtractionOut>(
      await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "reject", note: `LIF-09 rejected ${suffix}` },
      }),
      200,
    );
    expect(decided.status).toBe("rejected");

    // Act: member changes the vendor's name.
    const newName = `LIF-09 Renamed ${suffix}`;
    const response = await member.patch(`/api/vendors/${created.id}`, {
      data: { name: newName },
    });

    // Assert: the edit succeeds and the new name is persisted.
    const updated = await expectStatus<VendorOut>(response, 200);
    expect(updated.name).toBe(newName);

    const fetched = await expectStatus<VendorOut>(await member.get(`/api/vendors/${created.id}`), 200);
    expect(fetched.name).toBe(newName);
  });
});
